class Solution {
    public int[] avoidFlood(int[] rains) {
        int n = rains.length;
        int[] ans = new int[n];
        Map<Integer, Integer> fullLakeDay = new HashMap<>();
        TreeSet<Integer> dryDays = new TreeSet<>();

        for (int i = 0; i < n; i++) {
            int lake = rains[i];
            if (lake == 0) {
                ans[i] = 1;
                dryDays.add(i);
                continue;
            }

            ans[i] = -1;
            if (fullLakeDay.containsKey(lake)) {
                Integer dryDay = dryDays.higher(fullLakeDay.get(lake));
                if (dryDay == null) return new int[0];
                ans[dryDay] = lake;
                dryDays.remove(dryDay);
            }
            fullLakeDay.put(lake, i);
        }
        return ans;
    }
}
